import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"矩阵计算","link":"/api/SIMD-API/tensor_api/matrix_compute/matrix_compute"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/cube_store_key_features"},{"text":"batch搬运","link":"/api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/batch_copy"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/batch_copy.md","filePath":"api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/batch_copy.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"搬运行为","slug":"搬运行为","link":"#搬运行为"}],"lastUpdated":1787967772000}'),l={name:"api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/batch_copy.md"};function t(e,s,o,_,d,h){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>batch搬运</h1><p>batch搬运是L0C Buffer到Global Memory或Unified Buffer（UB）搬运在矩阵最外层增加Batch维度的能力，用于一次完成多块矩阵计算结果的搬运。</p><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>源张量为<code>NZ</code>格式，目的张量支持<code>ND</code>、<code>DN</code>或<code>NZ</code>格式。用户只需要在构造layout时传入Batch参数，<code>copy</code>调用形式与非batch模式保持一致。</p><p>源张量可通过<code>make_frame_layout&lt;nz_layout_ptn&gt;(batch, m, n)</code>构造。目的张量可通过<code>make_frame_layout&lt;nd_layout_ptn&gt;(batch, m, n)</code>、<code>make_frame_layout&lt;dn_layout_ptn&gt;(batch, m, n)</code>、<code>make_frame_layout&lt;nd_ext_layout_ptn&gt;(batch, m, n)</code>、<code>make_frame_layout&lt;dn_ext_layout_ptn&gt;(batch, m, n)</code>或<code>make_frame_layout&lt;nz_layout_ptn, DstType&gt;(batch, m, n)</code>构造。</p><h2 id="搬运行为">搬运行为<a class="header-anchor" href="#搬运行为">​</a></h2><p>不传入<code>quant</code>或传入<code>uint64_t</code>类型的scalar量化参数时，不涉及量化张量的Batch维度匹配。接口按源张量的Batch数量完成搬运；scalar量化场景下所有Batch共用同一个量化参数：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">l0c</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l0c_addr</span><span class="p">),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nz_layout_ptn</span><span class="o">&gt;</span><span class="p">(</span><span class="n">batch</span><span class="p">,</span><span class="w"> </span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">));</span>
<span class="k">auto</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">dst_addr</span><span class="p">),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nd_ext_layout_ptn</span><span class="o">&gt;</span><span class="p">(</span><span class="n">batch</span><span class="p">,</span><span class="w"> </span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">));</span>

<span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_l0c_to_gm</span><span class="p">{}).</span><span class="n">with</span><span class="p">(</span><span class="n">l0c_to_gm_params</span><span class="p">{});</span>
<span class="n">copy</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">l0c</span><span class="p">);</span>

<span class="kt">uint64_t</span><span class="w"> </span><span class="n">quant</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">copy</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">l0c</span><span class="p">,</span><span class="w"> </span><span class="n">quant</span><span class="p">);</span>
</code></pre></div><p>传入Tensor API张量作为tensor量化参数时，量化张量可以不带Batch维度，也可以带Batch维度。不带Batch维度表示所有Batch共用同一份量化参数；带Batch维度表示每个Batch使用各自的量化参数，此时源张量、目的张量和量化张量都需要带Batch维度。</p><p>量化张量不带Batch维度时，接口复用同一份量化参数完成batch搬运：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">quant</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">quant_addr</span><span class="p">),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nd_ext_layout_ptn</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">));</span>

<span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_l0c_to_gm</span><span class="p">{}).</span><span class="n">with</span><span class="p">(</span><span class="n">l0c_to_gm_params</span><span class="p">{});</span>
<span class="n">copy</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">l0c</span><span class="p">,</span><span class="w"> </span><span class="n">quant</span><span class="p">);</span>
</code></pre></div><p>量化张量带Batch维度时，不能通过一条Fixpipe指令完成全部Batch搬运。接口会按Batch执行<code>for</code>循环，逐Batch使用对应的量化参数完成搬运：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">quant</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">quant_addr</span><span class="p">),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nd_ext_layout_ptn</span><span class="o">&gt;</span><span class="p">(</span><span class="n">batch</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">));</span>

<span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_l0c_to_gm</span><span class="p">{}).</span><span class="n">with</span><span class="p">(</span><span class="n">l0c_to_gm_params</span><span class="p">{});</span>
<span class="n">copy</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">l0c</span><span class="p">,</span><span class="w"> </span><span class="n">quant</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const m=a(l,[["render",t]]);export{i as __pageData,m as default};
